import base64, io, sys, zipfile
from pathlib import Path

APP = Path("/kaggle/working/app")
_PROJECT_B64 = ""

if not APP.exists():
    zipfile.ZipFile(io.BytesIO(base64.b64decode(_PROJECT_B64))).extractall(APP)
    print("project extracted to", APP)
sys.path.insert(0, str(APP))

from kaggle.bootstrap import *
install_deps()                      # pip deps
server = get_llama_server()         # prebuilt CUDA binary or ~20 min source build (cached)
model = download_model()            # ~12 GB GGUF (cached)
llama_proc = start_llama(server, model)   # llama-server across both T4s
backend_proc = start_backend()      # FastAPI + web UI
url = start_tunnel()                # public URL
smoke_test()                        # automated end-to-end test

print()
print("=" * 60)
print("OPEN THIS IN YOUR BROWSER:", url)
print("=" * 60)
